    private sealed class Fixture : IDisposable
    {
        public readonly string Root;
        public string DataFolder => Path.Combine(Root, "data");
        public string SchemasFolder => Path.Combine(Root, "schemas");
        public string MapPath => Path.Combine(Root, "map.json");
        public string FilePath => Path.Combine(DataFolder, "catalog.json");
        public DataProject Project { get; }
        public AgentSession Agent { get; }
        public Fixture(bool empty = false, bool readOnly = false, bool perFile = false, bool broken = false, bool map = true)
        {
            Root = Path.Combine(Path.GetTempPath(), "A045-owned", Guid.NewGuid().ToString("N"));
            Directory.CreateDirectory(DataFolder); Directory.CreateDirectory(SchemasFolder);
            File.WriteAllText(Path.Combine(SchemasFolder,"catalog.schema.json"), Schema, new UTF8Encoding(false));
            File.WriteAllText(Path.Combine(SchemasFolder,"records.schema.json"), """{"type":"object","properties":{"records":{"type":"array","items":{"type":"object","required":["id"],"properties":{"id":{"type":"string"}}}}}}""");
            if (!empty)
            {
                File.WriteAllText(FilePath, Data, new UTF8Encoding(false));
                File.WriteAllText(Path.Combine(DataFolder,"records.json"), """{"records":[{"id":"destA"},{"id":"destB"}]}""" + "\n");
            }
            if (broken) File.WriteAllText(Path.Combine(DataFolder,"broken.json"), "{broken");
            File.WriteAllText(MapPath,"""{"game":"Acceptance toys","labels":[{"file":"catalog.json","list":"/items","field":"name"}],"references":[{"file":"catalog.json","at":"/items/*/link","target":{"file":"records.json","list":"/records","key":"id"},"sentinels":["none"],"evidence":"Self-authored acceptance fixture."}]}""");
            Project = DataProject.Open(DataFolder,SchemasFolder,readOnly,perFile ? n => n == "catalog.json" ? "Generated by the toy maker; save its source instead." : null : null);
            Agent = new AgentSession(Project,map ? ReferenceMap.Read(File.ReadAllText(MapPath)) : null);
        }
        public DocumentSession<DataDocument> Session
        {
            get { var f = Project.Find("catalog.json")!; Assert.True(f.Open()); return f.Session!; }
        }
        public void Dispose()
        {
            var full = Path.GetFullPath(Root);
            var owner = Path.GetFullPath(Path.Combine(Path.GetTempPath(), "A045-owned"));
            if (!string.Equals(Path.GetDirectoryName(full),owner,StringComparison.OrdinalIgnoreCase) || !Guid.TryParseExact(Path.GetFileName(full),"N",out _))
                throw new InvalidOperationException("Refusing cleanup outside this test's owned GUID child.");
            if (Directory.Exists(full)) Directory.Delete(full,true);
        }
