    private sealed record Snapshot(DataDocument Current,long Revision,int Undo,bool Redo,int Journal,bool Dirty,byte[] Bytes,DateTime Mtime);
    private static Snapshot Before(Fixture f) => new(f.Session.Current,f.Session.Revision,f.Session.History.UndoCount,f.Session.History.CanRedo,f.Session.Journal.Count,f.Session.Dirty,File.ReadAllBytes(f.FilePath),File.GetLastWriteTimeUtc(f.FilePath));
    private static void Unchanged(Fixture f,Snapshot s)
    {
        Assert.Same(s.Current,f.Session.Current); Assert.Equal(s.Revision,f.Session.Revision);
        Assert.Equal(s.Undo,f.Session.History.UndoCount); Assert.Equal(s.Redo,f.Session.History.CanRedo);
        Assert.Equal(s.Journal,f.Session.Journal.Count); Assert.Equal(s.Dirty,f.Session.Dirty);
        Assert.Equal(s.Bytes,File.ReadAllBytes(f.FilePath)); Assert.Equal(s.Mtime,File.GetLastWriteTimeUtc(f.FilePath));
    }
    private static JsonObject Answer(JsonObject answer)
    {
        var hint = Assert.IsAssignableFrom<JsonValue>(answer["next"]).GetValue<string>();
        Assert.False(string.IsNullOrWhiteSpace(hint),answer.ToJsonString());
        // Round-trip proves normal responses contain JSON values, not display-only text.
        Assert.NotNull(JsonNode.Parse(answer.ToJsonString())); return answer;
    }
    private static IEnumerable<JsonNode> Nodes(JsonNode? n)
    {
        if (n is null) yield break;
        yield return n;
        if (n is JsonObject o) foreach (var p in o) foreach(var c in Nodes(p.Value)) yield return c;
        if (n is JsonArray a) foreach (var p in a) foreach(var c in Nodes(p)) yield return c;
    }
    private static IEnumerable<string> Strings(JsonNode n) => Nodes(n).OfType<JsonValue>().Where(v=>v.TryGetValue<string>(out _)).Select(v=>v.GetValue<string>());
    private static void Text(JsonNode n,string expected) => Assert.True(Strings(n).Any(s=>s.Contains(expected,StringComparison.OrdinalIgnoreCase)), $"Missing '{expected}' in {n.ToJsonString()}");
    private static void Value(JsonNode n,JsonNode? expected) => Assert.True(Nodes(n).Any(c=>JsonNode.DeepEquals(c,expected)), $"Missing JSON value {expected} in {n.ToJsonString()}");
    private static void Refusal(JsonObject a,string place,string rule)
    {
        Answer(a); Assert.True(a["refused"] is JsonArray refused && refused.Count>0 || a["error"] is JsonValue, a.ToJsonString()); Assert.False(a["applied"]?.GetValue<bool>()??false,a.ToJsonString()); Text(a,place);
        var diagnostic=string.Join(" ",Strings(a));
        var pattern=rule switch { "0"=>"(?i)(minimum|at least|>=|less than|too small|negative|zero)", "required"=>"(?i)(required|missing|must.*present)", "list"=>"(?i)(list|array)", "index"=>"(?i)(index|position)", _=>System.Text.RegularExpressions.Regex.Escape(rule) };
        Assert.Matches(pattern,diagnostic);
    }
    private static JsonObject Request(string method,JsonObject? parameters=null,JsonNode? id=null) => new() { ["jsonrpc"]="2.0",["id"]=id ?? JsonValue.Create(71),["method"]=method,["params"]=parameters ?? new JsonObject() };
    private static JsonObject Rpc(McpServer server,string method,JsonObject? parameters=null) => Assert.IsType<JsonObject>(server.Handle(Request(method,parameters).ToJsonString()));
    private static JsonObject Args(string tool) => tool switch
    {
        "ui_snapshot" or "describe" or "problems" or "save" => new JsonObject(),
        "find" => new JsonObject { ["file"]="catalog.json",["list"]="/items" },
        "get" => new JsonObject { ["file"]="catalog.json",["at"]="/items/0/name" },
        "set" => new JsonObject { ["file"]="catalog.json",["at"]="/items/0/amount",["value"]="9" },
        "insert" => new JsonObject { ["file"]="catalog.json",["list"]="/items",["index"]=1,["value"]=Item },
        "remove" => new JsonObject { ["file"]="catalog.json",["at"]="/items/1" },
        "undo" or "repair" => new JsonObject { ["file"]="catalog.json" },
        "refs" => new JsonObject { ["file"]="catalog.json",["at"]="/items/0" },   // Claude, 2026-11-01: the two added tools
        // Claude, 2026-11-01: the four file tools (the user's gap list, item 5).
        "create" => new JsonObject { ["file"]="spare.json",["schema"]="catalog.schema.json",["preview"]=true },
        "rename" => new JsonObject { ["file"]="catalog.json",["to"]="spare.json",["preview"]=true },
        "delete" => new JsonObject { ["file"]="catalog.json",["preview"]=true },
        "restore" => new JsonObject { ["file"]="catalog.json" },
        // Claude, 2026-11-01: the check tools (piece J).
        "checks" => new JsonObject(),
        "check" => new JsonObject { ["id"]="links.all" },
        // A335's proposal tools (schemas only here; behaviour is in EditProposalTests).
        "proposal_list" => new JsonObject { ["file"]="catalog.json" },
        "proposal_show" => new JsonObject { ["id"]="p1" },
        "proposal_accept" or "proposal_reject" => new JsonObject { ["id"]="p1",["digest"]="d" },
        "proposal_submit" => new JsonObject { ["file"]="catalog.json",["session"]="s",["revision"]=0,["operations"]=new JsonArray(new JsonObject { ["op"]="set",["at"]="/items/0/amount",["value"]=9 }),["checks"]=new JsonArray() },
        _ => throw new ArgumentOutOfRangeException(nameof(tool))
    };
    private static JsonObject Call(McpServer server,string tool,JsonObject? args=null) => Rpc(server,"tools/call",new JsonObject { ["name"]=tool,["arguments"]=args ?? Args(tool) });
    private static JsonObject ToolAnswer(JsonObject rpc)
    {
        var result = Assert.IsType<JsonObject>(rpc["result"]);
        Assert.False(result["isError"]?.GetValue<bool>() ?? false,rpc.ToJsonString());
        return ToolJson(result);
    }
    private static JsonObject ToolJson(JsonObject result)
    {
        foreach (var s in Strings(result))
        {
            if (!s.TrimStart().StartsWith('{')) continue;
            if (JsonNode.Parse(s) is JsonObject a && a.ContainsKey("next")) return Answer(a);
        }
        throw new Xunit.Sdk.XunitException("Tool result lacks the session's JSON answer with next: "+result.ToJsonString());
    }
    private static void BadTool(string tool,string field,JsonNode? value,bool omit=false)
    {
        using var f=new Fixture();
        if(tool=="save") f.Agent.Set("catalog.json","/items/0/amount","9");
        var s=Before(f); var a=Args(tool);
        if (omit) a.Remove(field); else a[field]=value;
        var result=Assert.IsType<JsonObject>(Call(new McpServer(f.Agent),tool,a)["result"]);
        Assert.True(ReferenceEquals(s.Current,f.Session.Current),"Invalid tool arguments changed the document: "+result.ToJsonString());
        Unchanged(f,s);
        Assert.True(result["isError"]?.GetValue<bool>() ?? false,result.ToJsonString());
        var answer=ToolJson(result); Assert.NotNull(answer["error"]);
    }
    private static void Got(JsonObject answer,string file,string at,JsonNode? expected)
    {
        Answer(answer); Assert.Equal(file,answer["file"]!.GetValue<string>()); Assert.Equal(at,answer["at"]!.GetValue<string>());
        Assert.True(answer.ContainsKey("value"),answer.ToJsonString()); Assert.True(JsonNode.DeepEquals(expected,answer["value"]),answer.ToJsonString());
    }
    private static void Applied(JsonObject answer,string at,JsonNode? after)
    {
        Answer(answer); Assert.True(answer["applied"]?.GetValue<bool>()??false,answer.ToJsonString());
        Assert.Equal(at,answer["at"]!.GetValue<string>()); Assert.True(JsonNode.DeepEquals(after,answer["after"]),answer.ToJsonString());
    }
    // Observed response metadata is the value at the same pointer before/after; middle removal shifts the next item there.
    private static void Preview(JsonObject answer,string at,JsonNode? before,JsonNode? after)
    {
        Answer(answer); Assert.True(answer["preview"]?.GetValue<bool>()??false,answer.ToJsonString());
        Assert.False(answer["applied"]?.GetValue<bool>()??false,answer.ToJsonString()); Assert.Null(answer["error"]); Assert.Null(answer["refused"]);
        Assert.Equal(at,answer["at"]!.GetValue<string>());
        Assert.True(JsonNode.DeepEquals(before,answer["before"]),answer.ToJsonString());
        Assert.True(JsonNode.DeepEquals(after,answer["after"]),answer.ToJsonString());
    }
    private void Style(string before,string after)
    {
        output.WriteLine("STYLE BEFORE: "+before); output.WriteLine("STYLE AFTER: "+after);
        var a=before.Split('\n'); var b=after.Split('\n'); Assert.Equal(a.Length,b.Length);
        var edited=Array.FindIndex(a,l=>l.Contains("Amber kite",StringComparison.Ordinal)); Assert.True(edited>=0);
        for(var i=0;i<a.Length;i++) if(i!=edited) Assert.Equal(a[i],b[i]);
        using var old=JsonDocument.Parse(before); using var now=JsonDocument.Parse(after);
        var prior=old.RootElement.GetProperty("items")[0]; var changed=now.RootElement.GetProperty("items")[0];
        Assert.Equal(prior.EnumerateObject().Select(x=>x.Name),changed.EnumerateObject().Select(x=>x.Name));
        Assert.Equal(9,changed.GetProperty("amount").GetInt32());
        foreach(var prop in prior.EnumerateObject()) if(prop.Name!="amount") Assert.True(JsonSchemas.Same(prop.Value,changed.GetProperty(prop.Name)));
        Assert.Contains("Amber kite",b[edited]); Assert.Contains("{",b[edited]); Assert.Contains("}",b[edited]);
    }

    private static void FoundItems(JsonObject a,int total,params string[] places)
    {
        Answer(a); Assert.Equal(total,a["matches"]!.GetValue<int>());
        var items=Assert.IsType<JsonArray>(a["items"]);
        Assert.Equal(places,items.Select(n=>n!["at"]!.GetValue<string>()).ToArray());
    }
    private static void NoDestination(JsonObject a,string expected)
    {
        if(a["link"] is null) { Assert.Equal("NotAReference",expected); return; }
        var link=Assert.IsType<JsonObject>(a["link"]); Assert.Equal(expected,link["outcome"]!.GetValue<string>());
        Assert.Null(link["file"]); Assert.Null(link["at"]);
    }
    private sealed record CliResult(int Exit,string Out,string Err);
    private static CliResult Process(Fixture f,string? input,params string[] call)
    {
        var assembly=typeof(AgentAcceptanceTests).Assembly.Location;
        var psi=new ProcessStartInfo("dotnet") { UseShellExecute=false,CreateNoWindow=true,RedirectStandardInput=true,RedirectStandardOutput=true,RedirectStandardError=true,WorkingDirectory=f.Root };
        foreach(var a in new[] { "exec","--runtimeconfig",Path.ChangeExtension(assembly,".runtimeconfig.json"),"--depsfile",Path.ChangeExtension(assembly,".deps.json"),typeof(Cli).Assembly.Location }.Concat(call.Contains("--data") ? call : new[] { "--data",f.DataFolder,"--schemas",f.SchemasFolder }.Concat(call))) psi.ArgumentList.Add(a);
        // Child-local settings; never mutate the test runner's environment or working directory.
        psi.Environment["DOTNET_CLI_TELEMETRY_OPTOUT"]="1"; psi.Environment["DOTNET_SKIP_FIRST_TIME_EXPERIENCE"]="1";
        psi.Environment["DOTNET_GENERATE_ASPNET_CERTIFICATE"]="false"; psi.Environment["DOTNET_ADD_GLOBAL_TOOLS_TO_PATH"]="false";
        using var p=System.Diagnostics.Process.Start(psi)!;
        var stdout=p.StandardOutput.ReadToEndAsync(); var stderr=p.StandardError.ReadToEndAsync();
        if(input is not null) p.StandardInput.Write(input); p.StandardInput.Close();
        if(!p.WaitForExit(30000)) { p.Kill(true); throw new Xunit.Sdk.XunitException("Owned CLI process exceeded 30s."); }
        return new(p.ExitCode,stdout.GetAwaiter().GetResult(),stderr.GetAwaiter().GetResult());
    }
    private CliResult Normal(Fixture f,int exit,params string[] call)
    {
        var r=Process(f,null,call); output.WriteLine($"CLI {string.Join(' ',call)}: exit {r.Exit}; stdout={r.Out}; stderr={r.Err}");
        Assert.Equal(exit,r.Exit); Answer(Assert.IsType<JsonObject>(JsonNode.Parse(r.Out))); return r;
    }

