    [Fact] public void Mcp_run_handles_blank_lines_and_suppresses_notifications()
    { using var f=new Fixture(); var text="\n  \n"+Request("ping").ToJsonString()+"\n\n"+"""{"jsonrpc":"2.0","method":"notifications/initialized"}"""+"\n"+Request("tools/list",id:JsonValue.Create("second")).ToJsonString()+"\n"; using var input=new StringReader(text); using var writer=new StringWriter(); new McpServer(f.Agent).Run(input,writer); var lines=writer.ToString().Split('\n',StringSplitOptions.RemoveEmptyEntries|StringSplitOptions.TrimEntries); Assert.Equal(2,lines.Length); Assert.Equal(71,JsonNode.Parse(lines[0])!["id"]!.GetValue<int>()); Assert.Equal("second",JsonNode.Parse(lines[1])!["id"]!.GetValue<string>()); }
    // Claude, 2026-11-01: refs and repair joined the tools (the user's gap list), then create, rename, delete and restore, so
    // the documented set is fifteen; then checks and check, seventeen.
    [Fact] public void Mcp_tools_list_has_all_described_tools_and_schemas()
    { using var f=new Fixture(); var a=Rpc(new McpServer(f.Agent),"tools/list"); var tools=Assert.IsType<JsonArray>(a["result"]!["tools"]); Assert.Equal(23,tools.Count); foreach(var name in new[]{"ui_snapshot","describe","find","get","problems","refs","repair","set","insert","remove","undo","save","create","rename","delete","restore","checks","check","proposal_submit","proposal_list","proposal_show","proposal_accept","proposal_reject"}) { var t=Assert.Single(tools.OfType<JsonObject>(),x=>x["name"]!.GetValue<string>()==name); Assert.False(string.IsNullOrWhiteSpace(t["description"]!.GetValue<string>())); Assert.IsType<JsonObject>(t["inputSchema"]); } }
    [Fact] public void Mcp_tool_input_schemas_are_checked_with_JsonSchemas()
    {
        using var f=new Fixture(); var tools=Assert.IsType<JsonArray>(Rpc(new McpServer(f.Agent),"tools/list")["result"]!["tools"]);
        var meta=new JsonSchemas().Add("shape", """{"type":"object","required":["type","properties"],"properties":{"type":{"const":"object"},"properties":{"type":"object","additionalProperties":{"type":"object"}},"required":{"type":"array","items":{"type":"string"}},"additionalProperties":{"type":"boolean"}}}""");
        foreach(var tool in tools.OfType<JsonObject>())
        {
            var name=tool["name"]!.GetValue<string>(); var schema=tool["inputSchema"]!;
            using var shape=JsonDocument.Parse(schema.ToJsonString()); Assert.Empty(meta.Validate(shape.RootElement,"shape"));
            var schemas=new JsonSchemas().Add("tool",schema.ToJsonString()); using var valid=JsonDocument.Parse(Args(name).ToJsonString()); Assert.Empty(schemas.Validate(valid.RootElement,"tool"));
            using var wrong=JsonDocument.Parse("[]"); Assert.NotEmpty(schemas.Validate(wrong.RootElement,"tool"));
            foreach(var prop in schema["properties"]!.AsObject())
            {
                var bad=Args(name); bad[prop.Key]=new JsonArray(1,2); using var sample=JsonDocument.Parse(bad.ToJsonString()); Assert.NotEmpty(schemas.Validate(sample.RootElement,"tool"));
            }
        }
    }
