    [Fact] public void Cli_readonly_save_is_refused_and_preserves_disk() { using var f=new Fixture(); var s=Before(f); var r=Normal(f,1,"--read-only","set","catalog.json","/items/0/amount","9","--save"); var a=Assert.IsType<JsonObject>(JsonNode.Parse(r.Out)); Applied(a,"/items/0/amount",JsonValue.Create(9)); var save=Assert.IsType<JsonObject>(a["save"]); Answer(save); Assert.Empty(Assert.IsType<JsonArray>(save["saved"])); var refusal=Assert.Single(Assert.IsType<JsonArray>(save["refused"])); Assert.Equal("catalog.json",refusal!["file"]!.GetValue<string>()); Text(refusal,"read-only"); Unchanged(f,s); }
    [Fact] public void Cli_mcp_serves_real_stdin_stdout_lines()
    {
        using var f=new Fixture(); var input="\n"+Request("initialize",new JsonObject{["protocolVersion"]="2042-01-02"}).ToJsonString()+"\n"+"""{"jsonrpc":"2.0","method":"notifications/initialized"}"""+"\n\n"+Request("tools/call",new JsonObject{["name"]="describe",["arguments"]=new JsonObject()},JsonValue.Create("tools-id")).ToJsonString()+"\n";
        var r=Process(f,input,"mcp"); output.WriteLine(r.Out); Assert.Equal(0,r.Exit); var lines=r.Out.Split('\n',StringSplitOptions.RemoveEmptyEntries|StringSplitOptions.TrimEntries); Assert.Equal(2,lines.Length); Text(JsonNode.Parse(lines[0])!,"2042-01-02"); var tool=Assert.IsType<JsonObject>(JsonNode.Parse(lines[1])); Assert.Equal("tools-id",tool["id"]!.GetValue<string>()); Text(ToolAnswer(tool),"Kite catalogue");
    }
    private void BadCli(Fixture f,params string[] args)
    { var s=Before(f); var r=Process(f,null,args); output.WriteLine($"CLI bad arguments: {string.Join(' ',args)}; exit={r.Exit}; stdout={r.Out}; stderr={r.Err}"); Assert.Equal(2,r.Exit); Assert.False(string.IsNullOrWhiteSpace(r.Err)); if(!string.IsNullOrWhiteSpace(r.Out)) Assert.NotNull(JsonNode.Parse(r.Out)); Unchanged(f,s); }
    [Fact] public void Cli_missing_call_is_exit_two() { using var f=new Fixture(); BadCli(f); }
    [Fact] public void Cli_unknown_call_is_exit_two() { using var f=new Fixture(); BadCli(f,"unknown-call"); }
    [Fact] public void Cli_missing_set_value_is_exit_two() { using var f=new Fixture(); BadCli(f,"set","catalog.json","/items/0/amount"); }
    [Fact] public void Cli_noninteger_insert_index_is_exit_two() { using var f=new Fixture(); BadCli(f,"insert","catalog.json","/items","wrong-index",Item); }
    [Fact] public void Cli_missing_data_folder_is_exit_two() { using var f=new Fixture(); BadCli(f,"--data",Path.Combine(f.Root,"absent"),"--schemas",f.SchemasFolder,"describe"); }
    [Fact] public void Cli_unreadable_map_is_exit_two() { using var f=new Fixture(); BadCli(f,"--map",Path.Combine(f.Root,"absent-map.json"),"describe"); }
    [Fact] public void Cli_malformed_map_is_exit_two() { using var f=new Fixture(); File.WriteAllText(f.MapPath,"{bad"); BadCli(f,"--map",f.MapPath,"describe"); }

    [Fact] public void First_user_observations_record_public_answers_without_source_oracle()
    {
        using var f=new Fixture();
        output.WriteLine("CALL 1 describe: "+Answer(f.Agent.Describe()).ToJsonString());
        output.WriteLine("CALL 2 get mapped id: "+Answer(f.Agent.Get("catalog.json","/items/0/link")).ToJsonString());
        output.WriteLine("GET SCALAR: "+Answer(f.Agent.Get("catalog.json","/switch")).ToJsonString());
        output.WriteLine("FIND LIMIT: "+Answer(f.Agent.Find("catalog.json","/items",limit:1)).ToJsonString());
        output.WriteLine("PREVIEW: "+Answer(f.Agent.Set("catalog.json","/items/0/amount","9",true)).ToJsonString());
        output.WriteLine("REFUSAL: "+Answer(f.Agent.Set("catalog.json","/items/0/amount","-1")).ToJsonString());
        output.WriteLine("ISOLATED INVALID-ARGUMENT PROTOCOL PROBE (not a suggested workflow): "+Call(new McpServer(f.Agent),"insert",new JsonObject{["file"]="catalog.json",["list"]="/items",["value"]=Item}).ToJsonString());
    }
